def universe() -> list[dict]:
    unique = {}
    for theme, source in GROUPS.items():
        for entry in source.split(";"):
            code, name = entry.strip().split(" ", 1)
            # 600837 merged and delisted; historical names are not a current universe.
            if code == "600837":
                continue
            board = "20cm" if code.startswith(("30", "68")) else "30cm" if code[0] in "48" else "10cm"
            unique[code] = {"code": code, "name": name, "board": board, "theme_tags": [theme]}
    return list(unique.values())
